<?php $pageTitle='Courses';require_once __DIR__.'/functions.php';$courses=db()->query("SELECT * FROM courses ORDER BY id DESC")->fetchAll();include 'includes/header.php';?><section class="page-head"><div class="container"><h1>Courses</h1><p class="muted">Courses are managed from the Admin Panel.</p></div></section><section class="section" style="padding-top:10px"><div class="container cards"><?php foreach($courses as $c):?><article class="card"><div class="thumb"><?=e($c['icon'])?></div><div class="card-body"><h3><?=e($c['title'])?></h3><p><?=e($c['description'])?></p><div class="meta"><span>👨‍🏫 Hrithik</span><span>🔍 <?=e($c['level'])?></span><span>⏱ <?=e($c['duration'])?></span><span>📚 <?=e($c['lessons'])?> lessons</span><span><?=e($c['language'])?></span></div><div class="price"><?=e($c['price'])?></div><a class="primary" style="margin-top:14px" href="course.php?slug=<?=urlencode($c['slug'])?>">View Course</a></div></article><?php endforeach;?></div></section><?php include 'includes/footer.php';?>
